<script setup>
import { deviceChoices } from '../../deviceCatalog.js'
import DeviceSelect from '../DeviceSelect.vue'
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { Plus } from '@lucide/vue'
import { can } from '../../permissions.js'
import { session } from '../../api.js'
import { createClientId } from '../../clientId.js'
import { responseRead, responseWrite } from '../../response/api.js'
import { actionLabels, correctedMilestones, evidenceKinds, evidencePayload, executionActions, milestonePayload, responseTime, sourceLabels, stateLabel, systemEvents } from '../../response/helpers.js'
import ResponseEvidenceEditor from './ResponseEvidenceEditor.vue'
const props=defineProps({items:{type:Array,default:()=>[]},procedures:{type:Array,default:()=>[]},devices:{type:Array,default:()=>[]},selected:Object,deviceId:String,alarmId:String,staff:{type:Array,default:()=>[]}})
const emit=defineEmits(['refresh','select','evaluate','navigate'])
const dialog=ref(false),kind=ref('plan'),busy=ref(false),error=ref(''),form=reactive({}),staffOptions=ref([]),staffLoading=ref(false),systemSources=ref([]),sourceError=ref('')
let generation=0,staffGeneration=0,disposed=false
const deviceName=id=>props.devices.find(d=>d.id===id)?.name||id
const selectedBody=computed(()=>props.selected?.body),selectedDevices=computed(()=>deviceChoices(props.selected?.deviceIds||[],props.devices)),planProcedure=computed(()=>props.procedures.find(row=>row.id===form.procedureRevisionId))
const rows=computed(()=>props.items.filter(row=>(!props.deviceId||row.deviceIds.includes(props.deviceId))&&(!props.alarmId||row.body.alarmId===props.alarmId)))
const manualSteps=computed(()=>selectedBody.value?.procedure.steps.filter(s=>!s.systemEventType)||[]),systemSteps=computed(()=>selectedBody.value?.procedure.steps.filter(s=>s.systemEventType)||[])
const editableRecord=computed(()=>selectedBody.value&&['RUNNING','RECORDING','ENDED','REVIEWED'].includes(selectedBody.value.status)),timeline=computed(()=>correctedMilestones(selectedBody.value?.milestones))
function initialise(type,value={}){kind.value=type;error.value='';sourceError.value='';Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,value,{idempotencyKey:createClientId()});dialog.value=true}
function plan(row,source='DRILL'){const body=row?.body||{};initialise('plan',{resourceId:row?.resourceId||createClientId(),expectedVersion:row?.version||0,source:body.source||source,name:body.name||'',deviceIds:[...(row?.deviceIds||(props.deviceId?[props.deviceId]:[]))].filter(Boolean),procedureRevisionId:body.procedureRevisionId||'',people:(body.people||[{username:session.user,role:''}]).map(v=>({...v})),range:body.plannedStart?[body.plannedStart,body.plannedEnd]:null,alarmId:body.alarmId||props.alarmId||'',alarmReportEventId:body.alarmReportEventId||'',evidenceRange:null})}
function action(value){initialise('action',{action:value,reason:''})}
function milestone(row){initialise('milestone',{stepId:row?.stepId||manualSteps.value[0]?.id||'',occurredAt:row?.occurredAt||null,executor:row?.executor||session.user,status:'UNVERIFIED',explanation:'',correctsId:row?.id||'',evidence:[]})}
function system(){initialise('system',{stepId:systemSteps.value[0]?.id||'',sourceEventId:'',deviceId:props.selected.deviceIds[0]||'',queryRange:[Math.max(1,(selectedBody.value.startedAt||Date.now())-86400000),Date.now()]})}
function simulation(){initialise('simulation',{deviceId:props.selected.deviceIds[0]||'',occurredAt:null,content:''})}
function association(row){initialise('association',{sourceKind:row?.source?.kind||'ALARM_REPORT',sourceId:row?.source?.sourceId||'',deviceId:row?.source?.deviceId||props.selected.deviceIds[0],classification:row?.classification||'UNCLASSIFIED',status:'UNVERIFIED',containsProduction:row?.containsProduction??true,basis:'',evidence:[],queryRange:[Math.max(1,(selectedBody.value.startedAt||Date.now())-86400000),Date.now()]})}
async function loadStaff(){const token=++staffGeneration,ids=kind.value==='plan'?form.deviceIds:props.selected?.deviceIds;staffOptions.value=[];if(!ids?.length)return;staffLoading.value=true;try{const value=await responseRead('response-staff','','',{deviceIds:ids.join(',')});if(token===staffGeneration&&!disposed)staffOptions.value=value.items||[]}catch(cause){if(token===staffGeneration&&!disposed)error.value=cause.message}finally{if(token===staffGeneration)staffLoading.value=false}}
async function loadSources(){const token=++staffGeneration;if(!props.selected||!form.deviceId||!form.queryRange?.[0]||!(form.queryRange[1]>form.queryRange[0]))return;systemSources.value=[];sourceError.value='';try{const value=await responseRead('response-runs',props.selected.resourceId,'evidence-candidates',{kind:kind.value==='system'?'ALARM_LIFECYCLE':form.sourceKind,deviceId:form.deviceId,start:form.queryRange[0],end:form.queryRange[1],limit:100,offset:0});if(token!==staffGeneration||disposed)return;systemSources.value=value.items||[];if(value.total>systemSources.value.length||value.readLimitReached)sourceError.value='来源查询达到展示或读取上限，请缩小资料区间。'}catch(cause){if(token===staffGeneration&&!disposed)sourceError.value=cause.message}}
async function save(){if(busy.value)return;const token=generation;busy.value=true;error.value='';try{let result;const row=props.selected,id=row?.resourceId,common={expectedVersion:row?.version,idempotencyKey:form.idempotencyKey};if(kind.value==='plan'){if(!form.name.trim()||!form.deviceIds.length||!planProcedure.value?.body.published||form.people.some(p=>!p.username||!p.role.trim())||new Set(form.people.map(p=>p.username)).size!==form.people.length)throw Error('请明确计划名称、范围、已发布流程、人员与责任岗位');if(form.source==='DRILL'&&(!form.range||form.range[1]<=form.range[0]))throw Error('请填写有效计划区间');if(form.source==='REAL_CASE'&&!form.alarmId)throw Error('真实案例须引用获授权的生产告警');const body={name:form.name.trim(),procedureRevisionId:form.procedureRevisionId,people:form.people.map(p=>({username:p.username,role:p.role.trim()})),plannedStart:form.range?.[0]||0,plannedEnd:form.range?.[1]||0,alarmId:form.source==='REAL_CASE'?form.alarmId:'',alarmReportEventId:form.source==='REAL_CASE'?form.alarmReportEventId:'',evidenceStart:form.evidenceRange?.[0]||0,evidenceEnd:form.evidenceRange?.[1]||0};result=await responseWrite(form.source==='DRILL'?'drills':'response-cases',form.expectedVersion?form.resourceId:'','',{resourceId:form.resourceId,expectedVersion:form.expectedVersion,deviceIds:form.deviceIds.slice().sort(),idempotencyKey:form.idempotencyKey,body},form.expectedVersion?'PUT':'POST')}else if(kind.value==='action'){if(form.action==='CANCEL'&&!form.reason.trim())throw Error('取消须填写实际原因');result=await responseWrite(selectedBody.value.source==='DRILL'?'drills':'response-runs',id,'actions',{...common,action:form.action,reason:form.reason.trim()})}else if(kind.value==='milestone'){result=await responseWrite('response-runs',id,form.correctsId?'corrections':'milestones',milestonePayload(form,row,form.idempotencyKey))}else if(kind.value==='system'){if(!form.sourceEventId||!form.deviceId||!form.stepId)throw Error('请选择固定系统步骤与真实单次事务证据');result=await responseWrite('response-runs',id,'system-milestones',{...common,stepId:form.stepId,sourceEventId:form.sourceEventId,deviceId:form.deviceId})}else if(kind.value==='simulation'){if(!form.occurredAt||!form.content.trim())throw Error('请明确演练发生时间与实际模拟内容');result=await responseWrite('drills',id,'simulation-events',{...common,deviceId:form.deviceId,occurredAt:form.occurredAt,content:form.content.trim()})}else{if(!form.sourceId||!form.basis.trim())throw Error('具体样本引用与分类核实依据不能为空');result=await responseWrite('response-runs',id,'sample-associations',{...common,sourceKind:form.sourceKind,sourceId:form.sourceId,deviceId:form.deviceId,classification:form.classification,status:form.status,containsProduction:form.containsProduction,basis:form.basis.trim(),evidence:evidencePayload(form.evidence,row.deviceIds)})}if(token!==generation||disposed)return;dialog.value=false;emit('select',result);emit('refresh')}catch(cause){if(token===generation&&!disposed)error.value=cause.status===409?'执行版本已变化，操作未覆盖新资料。请刷新后重新核实。':cause.message}finally{if(token===generation)busy.value=false}}
watch(()=>[dialog.value,kind.value,form.deviceIds?.join(',')],()=>{if(dialog.value&&['plan','milestone'].includes(kind.value))loadStaff()})
watch(()=>[dialog.value,kind.value,form.deviceId,form.sourceKind,form.queryRange?.join(',')],()=>{if(dialog.value&&['system','association'].includes(kind.value))loadSources()})
watch(()=>props.alarmId,()=>{if(props.alarmId&&can('POST /api/v1/response-cases'))plan(null,'REAL_CASE')},{immediate:true})
onBeforeUnmount(()=>{disposed=true;generation++;staffGeneration++})
</script>
<template><section class="response-stack"><div class="response-toolbar"><p class="response-hint">演练计划与真实案例来源分开。真实案例不会更改告警状态，演练模拟仅写执行记录。</p><div class="response-actions"><ui-button v-if="can('POST /api/v1/drills')&&can('menu:devices')" type="primary" size="small" @click="plan()"><Plus/>编制演练计划</ui-button><ui-button v-if="can('POST /api/v1/response-cases')&&can('menu:alarms')&&can('menu:devices')" size="small" @click="plan(null,'REAL_CASE')">从真实告警建立案例</ui-button></div></div><div class="response-table-scroll"><ui-table :data="rows" empty-text="暂无演练计划或真实案例。"><ui-table-column label="执行 / 来源" min-width="210"><template #default="{row}">{{row.body.name}}<p class="response-meta">{{sourceLabels[row.body.source]}} · {{stateLabel(row.body.status)}} · 版本 {{row.version}}</p></template></ui-table-column><ui-table-column label="范围 / 时间" min-width="260"><template #default="{row}">{{row.deviceIds.map(deviceName).join('、')}}<p class="response-meta">计划 {{responseTime(row.body.plannedStart)}} 至 {{responseTime(row.body.plannedEnd)}}<br>实际 {{responseTime(row.body.startedAt)}} 至 {{responseTime(row.body.endedAt)}}</p></template></ui-table-column><ui-table-column label="操作" width="180"><template #default="{row}"><ui-button :data-response-execution="row.resourceId" text size="small" @click="emit('select',row)">时间线与复盘</ui-button><ui-button v-if="row.body.source==='DRILL'&&row.body.status==='DRAFT'&&can('PUT /api/v1/drills/:id')" text size="small" @click="plan(row)">编辑计划</ui-button></template></ui-table-column></ui-table></div>
<template v-if="selected"><div class="response-card response-stack"><div class="response-toolbar"><strong>{{selectedBody.name}} · {{sourceLabels[selectedBody.source]}}</strong><ui-tag>{{stateLabel(selectedBody.status)}} · 版本 {{selected.version}}</ui-tag></div><p class="response-meta">固定流程 {{selectedBody.procedure.name}} · {{selectedBody.procedureRevisionId}}<br>人员 {{selectedBody.people.map(p=>p.username+' · '+p.role).join('、')}}<br>可靠平台接收 {{responseTime(selectedBody.platformReceivedAt)}}</p><div class="response-actions"><ui-button v-for="value in executionActions(selectedBody)" v-show="can(selectedBody.source==='DRILL'?'POST /api/v1/drills/:id/actions':'POST /api/v1/response-runs/:id/actions')" :key="value" size="small" @click="action(value)">{{actionLabels[value]}}</ui-button><ui-button v-if="editableRecord&&can('POST /api/v1/response-runs/:id/milestones')&&manualSteps.length" size="small" @click="milestone()">登记人工现场节点</ui-button><ui-button v-if="editableRecord&&can('POST /api/v1/response-runs/:id/system-milestones')&&systemSteps.length" size="small" @click="system">关联真实系统节点</ui-button><ui-button v-if="selectedBody.source==='DRILL'&&['RUNNING','PUBLISHED'].includes(selectedBody.status)&&can('POST /api/v1/drills/:id/simulation-events')" size="small" @click="simulation">登记隔离模拟事件</ui-button><ui-button v-if="selectedBody.source==='DRILL'&&!['ARCHIVED','CANCELLED'].includes(selectedBody.status)&&can('POST /api/v1/response-runs/:id/sample-associations')" size="small" @click="association()">核实具体样本关联</ui-button><ui-button v-if="editableRecord&&can('POST /api/v1/response-runs/:id/evaluations')" type="primary" size="small" @click="emit('evaluate',selected)">生成固定复盘</ui-button></div><p class="response-hint">未记录现场动作仅表示缺少资料。平台确认只证明系统操作；流程、记录与证据的历史版本在复盘中固定。</p><div class="response-table-scroll"><table class="response-native-table"><thead><tr><th>步骤 / 责任岗位</th><th>前置与规定证据</th><th>计时起点 / 单位目标</th></tr></thead><tbody><tr v-for="s in selectedBody.procedure.steps" :key="s.id"><td>{{s.name}} · {{s.role}} · {{s.required?'必要':'选填'}}<p class="response-meta">{{s.systemEventType?systemEvents[s.systemEventType]:'人工现场节点'}}</p></td><td>{{s.prerequisites.map(id=>selectedBody.procedure.steps.find(s=>s.id===id)?.name||id).join('、') || '无前置步骤'}}<p>{{s.requiredEvidence.map(k=>evidenceKinds[k]||k).join('、') || '无额外规定证据'}}</p></td><td>{{s.clockStart==='RUN_START'?'实际开始':s.clockStart==='PLATFORM_RECEIVED'?'可靠平台接收':selectedBody.procedure.steps.find(row=>row.id===s.clockStart)?.name || s.clockStart}}<p>{{s.targetMs?s.targetMs+' ms':'未设目标'}}</p></td></tr></tbody></table></div></div><div class="response-card response-stack"><h3>发生与登记双时间线</h3><div class="response-table-scroll"><ui-table :data="timeline" empty-text="尚无节点记录，不推断现场已执行或未执行。"><ui-table-column label="节点 / 来源" min-width="190"><template #default="{row}">{{selectedBody.procedure.steps.find(s=>s.id===row.stepId)?.name || row.stepId}}<p class="response-meta">{{sourceLabels[row.source]}} · {{stateLabel(row.status)}}<br>{{row.superseded?'已被新记录更正':row.correctsId?'更正历史记录':'原始登记'}}</p></template></ui-table-column><ui-table-column label="实际发生 / 登记" min-width="230"><template #default="{row}">{{responseTime(row.occurredAt)}}<p class="response-meta">登记 {{responseTime(row.recordedAt)}}<br>执行 {{row.executor}} · 登记 {{row.recorder}}</p></template></ui-table-column><ui-table-column label="实际依据" min-width="290"><template #default="{row}">{{row.explanation}}<p v-for="ev in row.evidence" :key="ev.id" class="response-meta">{{evidenceKinds[ev.kind]}} · {{ev.description}} · {{stateLabel(ev.classification)}}</p></template></ui-table-column><ui-table-column label="操作" width="90"><template #default="{row}"><ui-button v-if="row.source==='MANUAL'&&!row.superseded&&editableRecord&&can('POST /api/v1/response-runs/:id/corrections')" text size="small" @click="milestone(row)">追加更正</ui-button></template></ui-table-column></ui-table></div><article v-for="ev in selectedBody.simulationEvents" :key="ev.id" class="response-card"><strong>隔离模拟 · {{deviceName(ev.deviceId)}}</strong><p>{{ev.content}}</p><p class="response-meta">发生 {{responseTime(ev.occurredAt)}} · 登记 {{responseTime(ev.recordedAt)}} · {{ev.recorder}}</p></article><article v-for="ev in selectedBody.sampleAssociations || []" :key="ev.id+ev.recordedAt" class="response-card"><strong>单次资料关联 · {{stateLabel(ev.classification)}} · {{stateLabel(ev.status)}}</strong><p>{{ev.basis}}</p><p class="response-meta">{{evidenceKinds[ev.source.kind]}} · {{ev.source.sourceId}} · {{responseTime(ev.recordedAt)}} · {{ev.reviewer}}</p><ui-button v-if="can('POST /api/v1/response-runs/:id/sample-associations')" size="small" text @click="association(ev)">追加分类核实</ui-button></article><p v-if="selectedBody.sampleAssociations?.length" class="response-hint">分类关联只适用于上述具体资料，生产告警和真实设备上报继续按原业务处理。</p></div></template></section>
<ui-dialog v-model="dialog" :title="kind==='plan'?(form.source==='DRILL'?'编制演练计划':'建立真实处置案例'):kind==='milestone'?'登记或更正人工节点':kind==='system'?'关联已提交系统事务':kind==='simulation'?'登记隔离模拟事件':kind==='association'?'核实单次资料关联':actionLabels[form.action]" width="min(920px,94vw)" :close-on-click-modal="false" @close="dialog=false"><div class="response-dialog-body"><ui-alert v-if="error" :title="error" type="error" :closable="false"/><ui-form label-position="top" :disabled="busy"><template v-if="kind==='plan'"><ui-form-item label="计划或案例名称" required><ui-input v-model="form.name"/></ui-form-item><ui-form-item label="明确设备范围" required><DeviceSelect v-model="form.deviceIds" multiple :disabled="!!deviceId"/></ui-form-item><ui-form-item label="已发布固定流程版本" required><ui-select v-model="form.procedureRevisionId" filterable><ui-option v-for="p in procedures.filter(p=>p.body.published&&form.deviceIds.every(id=>p.deviceIds.includes(id)))" :key="p.id" :value="p.id" :label="`${p.body.name} · 版本 ${p.version}`"/></ui-select></ui-form-item><ui-form-item v-if="form.source==='DRILL'" label="计划开始与结束" required><ui-date-range v-model="form.range"/></ui-form-item><template v-else><ui-form-item label="获授权生产告警 ID" required><ui-input v-model="form.alarmId" :disabled="!!alarmId"/></ui-form-item><ui-form-item label="具体单次告警上报 ID（选填）"><ui-input v-model="form.alarmReportEventId"/></ui-form-item><ui-form-item v-if="form.alarmReportEventId" label="单次上报证据区间"><ui-date-range v-model="form.evidenceRange"/></ui-form-item><p class="response-hint">可靠平台接收时间仅从指定单次上报和归档读取，缺失时保留未知；不采用聚合告警时间替代。</p></template><article v-for="(p,index) in form.people" :key="index" class="response-card response-grid"><ui-form-item :label="'人员 '+(index+1)" required><ui-select v-model="p.username" filterable :loading="staffLoading"><ui-option v-for="s in staffOptions" :key="s.username" :value="s.username" :label="s.displayName || s.username"/></ui-select></ui-form-item><ui-form-item :label="'实际责任岗位 '+(index+1)" required><ui-select v-model="p.role" filterable allow-create><ui-option v-for="role in [...new Set(planProcedure?.body.steps.map(s=>s.role)||[])]" :key="role" :value="role" :label="role"/></ui-select></ui-form-item><ui-button text size="small" @click="form.people.splice(index,1)">移除人员</ui-button></article><ui-button size="small" @click="form.people.push({username:'',role:''})">增加实际人员</ui-button><p class="response-hint">仅选择本次设备范围内具备复盘权限的实际启用人员。计划发布和开始通过独立操作执行。</p></template>
<template v-else-if="kind==='action'"><p>当前 {{stateLabel(selectedBody.status)}} · {{selectedBody.name}} · 固定执行版本 {{selected.version}}</p><ui-form-item :label="form.action==='CANCEL'?'取消原因':'本次操作依据（选填）'"><ui-input v-model="form.reason" type="textarea" :rows="3"/></ui-form-item><p class="response-hint">归档执行不自动关闭整改，开始后保留流程与人员快照。</p></template><template v-else-if="kind==='milestone'"><div class="response-grid"><ui-form-item label="人工现场步骤" required><ui-select v-model="form.stepId" :disabled="!!form.correctsId"><ui-option v-for="s in manualSteps" :key="s.id" :value="s.id" :label="s.name"/></ui-select></ui-form-item><ui-form-item label="实际发生时间" required><ui-date-time v-model="form.occurredAt" disable-future/></ui-form-item><ui-form-item label="实际执行人" required><ui-select v-model="form.executor" filterable :loading="staffLoading"><ui-option v-for="s in staffOptions" :key="s.username" :value="s.username" :label="s.displayName || s.username"/></ui-select></ui-form-item><ui-form-item label="节点确认状态"><ui-select v-model="form.status"><ui-option value="UNVERIFIED" label="未确认"/><ui-option value="CONFIRMED" label="已核实确认"/><ui-option value="DISPUTED" label="存在争议"/></ui-select></ui-form-item></div><ui-form-item label="实际依据及更正说明" required><ui-input v-model="form.explanation" type="textarea" :rows="3"/></ui-form-item><ResponseEvidenceEditor v-model="form.evidence" :devices="selectedDevices" :execution-id="selected.resourceId" :disabled="busy"/><p class="response-hint">登记时间、登记人由服务器保存。补登记与更正产生新版本，不覆盖已确认复盘。</p></template>
<template v-else-if="kind==='system'"><ui-form-item label="固定系统步骤" required><ui-select v-model="form.stepId"><ui-option v-for="s in systemSteps" :key="s.id" :value="s.id" :label="`${s.name} · ${systemEvents[s.systemEventType]}`"/></ui-select></ui-form-item><ui-form-item label="事务来源设备" required><ui-select v-model="form.deviceId"><ui-option v-for="d in selectedDevices" :key="d.id" :value="d.id" :label="d.name || d.id"/></ui-select></ui-form-item><ui-form-item label="资料查询区间"><ui-date-range v-model="form.queryRange"/></ui-form-item><ui-alert v-if="sourceError" :title="sourceError" type="warning" :closable="false"/><ui-form-item label="实际提交系统事务" required><ui-select v-model="form.sourceEventId" filterable placeholder="选择获授权且类型一致的实际事务"><ui-option v-for="ev in systemSources.filter(ev=>ev.eventType===systemSteps.find(s=>s.id===form.stepId)?.systemEventType)" :key="ev.sourceId" :value="ev.sourceId" :label="`${systemEvents[ev.eventType]} · ${responseTime(ev.occurredAt)} · ${ev.sourceId.slice(-8)}`"/></ui-select></ui-form-item><p class="response-hint">服务器核实具体事务、类型、权限与时钟。系统操作仅证明该平台动作，不推断通知或到场。</p></template>
<template v-else-if="kind==='simulation'"><ui-form-item label="演练设备"><ui-select v-model="form.deviceId"><ui-option v-for="d in selectedDevices" :key="d.id" :value="d.id" :label="d.name || d.id"/></ui-select></ui-form-item><ui-form-item label="模拟发生时间" required><ui-date-time v-model="form.occurredAt" disable-future/></ui-form-item><ui-form-item label="明确模拟内容" required><ui-input v-model="form.content" type="textarea" :rows="4"/></ui-form-item><p class="response-hint">本次模拟只保存演练记录，不进入原始报文、解析、生产告警与通知链路。</p></template>
<template v-else><div class="response-grid"><ui-form-item label="单次资料来源"><ui-select v-model="form.sourceKind"><ui-option value="ALARM_REPORT" label="单次设备告警上报"/><ui-option value="RAW_MESSAGE" label="具体原始报文"/></ui-select></ui-form-item><ui-form-item label="资料设备"><ui-select v-model="form.deviceId"><ui-option v-for="d in selectedDevices" :key="d.id" :value="d.id" :label="d.name || d.id"/></ui-select></ui-form-item></div><ui-form-item label="资料查询区间"><ui-date-range v-model="form.queryRange"/></ui-form-item><ui-alert v-if="sourceError" :title="sourceError" type="warning" :closable="false"/><ui-form-item label="具体单次资料" required><ui-select v-model="form.sourceId" filterable><ui-option v-for="ev in systemSources" :key="ev.sourceId" :value="ev.sourceId" :label="`${evidenceKinds[ev.kind]} · ${responseTime(ev.occurredAt || ev.receivedAt)} · ${ev.sourceId.slice(-8)}`"/></ui-select></ui-form-item><div class="response-grid"><ui-form-item label="本次关联分类"><ui-select v-model="form.classification"><ui-option v-for="value in ['PRODUCTION','EXERCISE','TEST','UNCLASSIFIED']" :key="value" :value="value" :label="stateLabel(value)"/></ui-select></ui-form-item><ui-form-item label="分类核实状态"><ui-select v-model="form.status"><ui-option v-for="value in ['UNVERIFIED','CONFIRMED','DISPUTED']" :key="value" :value="value" :label="stateLabel(value)"/></ui-select></ui-form-item></div><ui-checkbox v-model="form.containsProduction">仍存在混入真实生产事件的可能</ui-checkbox><ui-form-item label="具体分类核实依据" required><ui-input v-model="form.basis" type="textarea" :rows="3"/></ui-form-item><ResponseEvidenceEditor v-model="form.evidence" :devices="selectedDevices" :execution-id="selected.resourceId" :disabled="busy"/><p class="response-hint">存在真实事件可能时保留生产分类；未确认资料不作测试排除。分类由服务器核实，不改变生产处理与通知。</p></template></ui-form></div><template #footer><ui-button :disabled="busy" @click="dialog=false">取消</ui-button><ui-button type="primary" :loading="busy" @click="save">{{kind==='plan'?'保存计划或案例':kind==='milestone'?'保存人工节点依据':kind==='system'?'关联真实系统事务':kind==='simulation'?'保存隔离模拟记录':kind==='association'?'保存具体分类核实':'确认本次操作'}}</ui-button></template></ui-dialog></template>
